let W=innerWidth,H=innerHeight,state='title',run=null,enemies=[],shots=[],zones=[],gems=[],effects=[],keys={},touch=null,mouse={x:0,y:0},last=0,spawnTimer=0,shopOffers=[],shopVisits=0;
let best=0;try{best=Number(localStorage.getItem('lucky-best')||0)}catch{}
