function updateHud(){if(!run)return;$('#hp').style.width=(run.hp/run.maxHp*100)+'%';$('#health').textContent=Math.ceil(run.hp)+' / '+run.maxHp;$('#time').textContent=isBossWave()?'BOSS':Math.max(0,waveDuration()-Math.floor(run.t)).toString().padStart(2,'0');$('#wave').textContent=`${run.cheated?'CHEATS · ':run.endless?'ENDLESS · ':''}WAVE ${run.wave}${run.endless?'':' / 10'} · ${run.cash} MATERIALS`;$('#level').textContent=run.wave;$('#xp').style.width=(isBossWave()?100:run.t/waveDuration()*100)+'%';$('#kills').textContent=run.kills+' defeated';$('#dash').disabled=run.dash>0;$('#dashtext').textContent=run.dash>0?run.dash.toFixed(1)+'s':'READY';$('#survivor-name').textContent=run.char.name;$('#wallet-hud').textContent='✦ '+run.cash;$('#skill').style.display=abilityCount()?'block':'none';const skills=Object.keys(run.gear).filter(id=>gear[id].type==='ability');$('#skilltext').textContent=skills.some(id=>(run.cool[id]||0)<=0)?'READY':skills.length?Math.min(...skills.map(id=>run.cool[id]||0)).toFixed(1)+'s':'';$('#skill').disabled=skills.length>0&&!skills.some(id=>(run.cool[id]||0)<=0);$('#build').innerHTML=Object.entries(run.gear).filter(([id])=>gear[id].type==='weapon').map(([id,l])=>`<span class="badge" style="color:${gear[id].color}">${gear[id].icon} ${esc(gear[id].name)} <b>${l}</b></span>`).join('')}
function cost(id){return Math.round(gear[id].price*(1+.28*amount(id))*(run.char.id==='engineer'?.8:1))}
function available(){return Object.keys(gear).filter(id=>(!gear[id].fusion||run.unlocked.includes(id))&&amount(id)<MAX&&(amount(id)>0||!slotFull(id)))}
function rollShop(){const pool=available(),owned=pool.filter(id=>amount(id)>0);shopOffers=[];if(owned.length)shopOffers.push(owned[Math.floor(Math.random()*owned.length)]);while(shopOffers.length<4&&pool.length){let id=pool[Math.floor(Math.random()*pool.length)];pool.splice(pool.indexOf(id),1);if(!shopOffers.includes(id))shopOffers.push(id)}}
function openShop(){progress('wave',run.wave);state='shop';shopVisits++;run.rerolls=0;rollShop();renderShop()}
function renderShop(){shopOffers=shopOffers.filter(id=>available().includes(id));const fusionCards=recipes.map(([a,b,out])=>{const ready=amount(a)===MAX&&amount(b)===MAX;const made=run.unlocked.includes(out);return `<div class="recipe ${ready?'ready':''}"><div><strong style="color:${gear[out].color}">${gear[out].icon} ${gear[out].name}</strong><p>${gear[a].name} <b>${amount(a)}/5</b> + ${gear[b].name} <b>${amount(b)}/5</b></p><small>${gear[out].desc}</small></div>${ready?`<button data-fuse="${out}" class="primary">FUSE</button>`:`<span class="recipe-tag">${made?'UNLOCKED':'MAX BOTH'}</span>`}</div>`}).join('');
 overlay(`<div class="shop-head"><div><div class="eyebrow">WAVE ${run.wave} CLEARED</div><h2>Make your luck.</h2></div><div class="wallet">✦ ${run.cash}<small>MATERIALS</small></div></div><p class="shop-intro">Buy duplicate gear to upgrade it. All gear maxes at level 5.<br>${weaponCount()} / ${weaponCap()} weapon slots · ${itemCount()} / ${ITEM_CAP} item slots · ${abilityCount()} / ${ABILITY_CAP} ability slot · dash separate · full categories offer owned upgrades only. Trash gear to open a slot.</p><div class="shop-cards">${shopOffers.map((id,i)=>{let g=gear[id],lv=amount(id),full=!lv&&slotFull(id);return `<button class="card offer" data-buy="${i}" style="--rarity:${g.color}" ${run.cash<cost(id)?'disabled':''}><div class="icon" style="color:${g.color}">${g.icon}</div><small>${g.fusion?'FUSION':g.type.toUpperCase()} · ${lv?'UPGRADE '+lv+' → '+(lv+1):'LEVEL 1'}</small><strong>${g.name}</strong><p>${g.desc}</p><div class="price">${full?'SWAP · ✦ '+cost(id):'✦ '+cost(id)}</div></button>`}).join('')}${shopOffers.length?'':'<p class="hint">No eligible offers remain. Trash or sell gear to open a slot, then reroll.</p>'}</div>${run.char.id!=='arsenal'?`<div class="slot-upgrade"><div><small>ARMORY EXPANSION</small><strong>Carry another weapon</strong><p>${weaponCap()} weapon slots · lasts for this run</p></div><button id="buy-slot" ${run.cash<weaponSlotPrice()?'disabled':''}>${'+1 SLOT · ✦ '+weaponSlotPrice()}</button></div>`:''}<div class="shop-actions"><button id="reroll" ${run.cash<rerollCost()?'disabled':''}>↻ Reroll · ${rerollCost()} materials</button><button class="primary" id="next">${(run.wave===9||(run.endless&&(run.wave+1)%5===0))?'FACE THE HOLLOW KING':'START WAVE '+(run.wave+1)} →</button></div><details open><summary>Your loadout · ${weaponCount()} / ${weaponCap()} weapons · ${itemCount()} / ${ITEM_CAP} items · ${abilityCount()} / ${ABILITY_CAP} ability slot · dash separate</summary><div class="inventory">${Object.entries(run.gear).map(([id,lv])=>`<div class="inv"><span style="color:${gear[id].color}">${gear[id].icon} ${gear[id].name}</span><b>${lv===5?'MAX':'LV '+lv}</b><button data-trash="${id}" aria-label="Trash ${gear[id].name}">Trash</button><button data-sell="${id}" aria-label="Sell ${gear[id].name}">Sell +${sellValue(id)}</button></div>`).join('')}</div></details><details><summary>Fusion lab · ${recipes.length} recipes</summary><p class="hint">Fuse two level-5 ingredients for free. Ingredients are consumed. ${run.char.id==='forgemaster'?'Your Forgemaster crafts fusions at a random level 2 or 3.':'The fusion starts at level 1.'} Once discovered, that fusion can appear in this run’s shop—even if sold. Buy copies to upgrade it to level 5.</p>${fusionCards}</details><p class="hint">Wave clear bonus and uncollected materials are added automatically. +12 HP before each wave.</p>`);
 $('#panel').classList.add('shop-panel');if($('#buy-slot'))$('#buy-slot').onclick=buyWeaponSlot;document.querySelectorAll('[data-trash]').forEach(b=>b.onclick=()=>trashGear(b.dataset.trash));document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>buy(Number(b.dataset.buy)));document.querySelectorAll('[data-fuse]').forEach(b=>b.onclick=()=>fuse(b.dataset.fuse));document.querySelectorAll('[data-sell]').forEach(b=>b.onclick=()=>sell(b.dataset.sell));$('#reroll').onclick=()=>{const p=rerollCost();if(run.cash<p)return;run.cash-=p;run.rerolls++;rollShop();renderShop()};$('#next').onclick=()=>{$('#panel').classList.remove('shop-panel');nextWave()};updateHud()}
function weaponCount(){return Object.keys(run.gear).filter(id=>gear[id].type==='weapon').length}
function weaponCap(){return run.char.id==='arsenal'?6:(run.char.id==='trailkeeper'?4:WEAPON_CAP)+(run.extraWeaponSlots||0)}
function weaponSlotPrice(){return 100+75*(run.extraWeaponSlots||0)}
function buyWeaponSlot(){if(state!=='shop'||run.char.id==='arsenal'||run.cash<weaponSlotPrice())return;run.cash-=weaponSlotPrice();run.extraWeaponSlots=(run.extraWeaponSlots||0)+1;renderShop();updateHud()}
function itemCount(){return Object.keys(run.gear).filter(id=>gear[id].type==='item').length}
function slotFull(id){return gear[id].type==='weapon'?weaponCount()>=weaponCap():gear[id].type==='ability'?abilityCount()>=ABILITY_CAP:itemCount()>=ITEM_CAP}
function rerollCost(){return 4+run.rerolls*3}
function buy(i){let id=shopOffers[i];if(!id||amount(id)>=5||run.cash<cost(id))return;if(!amount(id)&&slotFull(id)){chooseReplacement(i);return}run.cash-=cost(id);run.gear[id]=amount(id)+1;progress('purchases');if(amount(id)===5)progress('maxed');run.maxHp=maxHp();run.hp=Math.min(run.hp,run.maxHp);if(id==='heart')run.hp=Math.min(run.maxHp,run.hp+15);shopOffers.splice(i,1);renderShop()}
function trashGear(id){if(!amount(id))return;if(gear[id].type==='weapon'&&weaponCount()<=1){showToast('Keep at least one weapon.');return}delete run.gear[id];delete run.cool[id];if(id==='furySkill')run.furyTime=0;if(id==='renewalSkill')run.renewalTime=0;run.maxHp=maxHp();run.hp=Math.min(run.hp,run.maxHp);renderShop()}
function chooseReplacement(i){const id=shopOffers[i];overlay(`<div class="eyebrow">${gear[id].type.toUpperCase()} SLOTS FULL</div><h2>Make room for ${gear[id].name}</h2><p>Choose one to trash. The new gear costs ${cost(id)} materials.<br>Your replacement starts at level 1.</p><div class="inventory">${Object.entries(run.gear).filter(([old])=>gear[old].type===gear[id].type).map(([old,lv])=>`<button data-replace="${old}" class="card"><strong>${gear[old].name} · LV ${lv}</strong><p>Trash and replace →</p></button>`).join('')}</div><button id="cancel-swap">Cancel</button>`);document.querySelectorAll('[data-replace]').forEach(b=>b.onclick=()=>{if(run.cash<cost(id)){renderShop();return}const old=b.dataset.replace;delete run.gear[old];delete run.cool[old];if(old==='furySkill')run.furyTime=0;if(old==='renewalSkill')run.renewalTime=0;buy(i)});$('#cancel-swap').onclick=renderShop}
function sellValue(id){return Math.floor(gear[id].price*amount(id)*.45)}
function sell(id){if(!amount(id))return;if(gear[id].type==='weapon'&&weaponCount()<=1)return;run.cash+=sellValue(id);delete run.gear[id];run.maxHp=maxHp();run.hp=Math.min(run.hp,run.maxHp);renderShop()}
function fuse(out){const recipe=recipes.find(r=>r[2]===out);if(!recipe)return;const [a,b]=recipe;if(amount(a)!==5||amount(b)!==5)return;if(!amount(out)&&Object.keys(run.gear).filter(id=>id!==a&&id!==b&&gear[id].type===gear[out].type).length>=(gear[out].type==='weapon'?weaponCap():gear[out].type==='item'?ITEM_CAP:ABILITY_CAP))return;progress('fusions');delete run.gear[a];delete run.gear[b];const fusionLevel=run.char.id==='forgemaster'?2+Math.floor(Math.random()*2):1;run.gear[out]=Math.min(5,amount(out)+fusionLevel);if(!run.unlocked.includes(out))run.unlocked.push(out);run.maxHp=maxHp();run.hp=Math.min(run.hp,run.maxHp);shopOffers=shopOffers.filter(id=>id!==a&&id!==b);if(!shopOffers.includes(out)&&amount(out)<5)shopOffers.unshift(out);renderShop()}
function pause(){if(state==='playing'){state='paused';overlay(`<div class="eyebrow">TAKE A BREATHER</div><h2>Run paused.</h2><p>Wave ${run.wave} · ${run.kills} defeated · ${run.cash} materials</p><button id="resume" class="primary">RESUME →</button><p><button id="quit">End run</button></p>`);$('#resume').onclick=pause;$('#quit').onclick=()=>finish(false)}else if(state==='paused'){state='playing';document.body.classList.add('playing');resetInput()}}
function finish(win){if(state==='ended')return;state='ended';if(win&&!run.victoryRecorded){run.victoryRecorded=true;if(!run.cheated&&run.char.id!=='ascendant'&&run.char.id!=='arsenal'&&run.char.id!=='trailkeeper'&&!championWins.includes(run.char.id)){championWins.push(run.char.id);progress('champions')}progress('wins');progress('wave',10)}saveProfile();best=Math.max(best,run.wave);try{localStorage.setItem('lucky-best',best)}catch{}updateHud();overlay(`<div class="eyebrow">${win?'THE HOLLOW KING HAS FALLEN':'EVERY RUN IS A NEW CHANCE'}</div><h1>${win?'FORTUNE<br><em>FAVORED YOU.</em>':'ONE MORE<br><em>RUN?</em>'}</h1><p>${run.char.name} · ${run.endless?'Endless wave '+run.wave:'Wave '+run.wave+' / 10'} · ${run.kills} defeated<br>${run.unlocked.length} fusions discovered · Best wave ${best}</p>${newUnlocks.length?`<div class="unlock-banner">SURVIVOR UNLOCKED<br><strong>${newUnlocks.join(' · ')}</strong></div>`:''}${win?'<button id="endless" class="primary">CONTINUE INTO ENDLESS ∞</button><p class="hint">Keep your build. Harder waves, a shop after every wave,<br>and a stronger Hollow King every 5 waves.</p>':''}<button id="again" class="primary">CHOOSE A SURVIVOR →</button>`);$('#panel').classList.remove('shop-panel');$('#again').onclick=choose;if(win)$('#endless').onclick=continueEndless}
function drawEnemy(e){const kind=e.kind||'chaser',colors={chaser:'#84936b',brute:'#c08b62',spitter:'#ab89ca',slime:'#69bd85',skitter:'#d8b76b',boss:'#d6789f'};ctx.save();ctx.translate(e.x,e.y);ctx.fillStyle='#0004';ctx.beginPath();ctx.ellipse(0,e.r*.75,e.r*1.1,e.r*.4,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=e.flash>0?'#fff':colors[kind];ctx.strokeStyle=e.boss?'#ffbbd8':'#cad3ae';ctx.lineWidth=1.5;
 if(kind==='slime'){ctx.beginPath();ctx.ellipse(0,Math.sin(run.total*5+e.x)*2,e.r,e.r*.8,0,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#b8f4c5';ctx.beginPath();ctx.arc(-e.r*.3,-e.r*.3,e.r*.18,0,Math.PI*2);ctx.fill()}
 else if(kind==='skitter'){ctx.strokeStyle='#d8b76b';ctx.lineWidth=3;for(let i=-1;i<=1;i++){ctx.beginPath();ctx.moveTo(-e.r, i*5);ctx.lineTo(-e.r-7,i*9+Math.sin(run.total*15)*3);ctx.moveTo(e.r,i*5);ctx.lineTo(e.r+7,i*9-Math.sin(run.total*15)*3);ctx.stroke()}ctx.beginPath();ctx.ellipse(0,0,e.r*.8,e.r*1.15,0,0,Math.PI*2);ctx.fill()}
 else{ctx.beginPath();const sides=kind==='brute'?6:kind==='boss'?8:5;for(let i=0;i<sides;i++){const a=i*Math.PI*2/sides-Math.PI/2;ctx.lineTo(Math.cos(a)*e.r,Math.sin(a)*e.r)}ctx.closePath();ctx.fill();ctx.stroke();if(kind==='brute'||e.boss){ctx.fillStyle=kind==='brute'?'#ebc49a':'#ffe693';ctx.beginPath();ctx.moveTo(-e.r*.7,-e.r*.4);ctx.lineTo(-e.r*.9,-e.r*1.3);ctx.lineTo(-e.r*.2,-e.r*.7);ctx.lineTo(0,-e.r*1.5);ctx.lineTo(e.r*.2,-e.r*.7);ctx.lineTo(e.r*.9,-e.r*1.3);ctx.lineTo(e.r*.7,-e.r*.4);ctx.fill()}if(kind==='spitter'){ctx.fillStyle='#d9b8f8';ctx.beginPath();ctx.arc(0,8,6,0,Math.PI*2);ctx.fill()}}
 ctx.fillStyle=e.boss?'#ffe8aa':'#17251d';ctx.fillRect(-e.r*.42,-4,4,5);ctx.fillRect(e.r*.2,-4,4,5);
 if(e.wind>0){ctx.strokeStyle='#ffbc87';ctx.lineWidth=3;if(kind==='brute'){ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(e.cx*225,e.cy*225);ctx.stroke()}else{ctx.beginPath();ctx.arc(0,0,e.r+8+Math.sin(run.total*15)*2,0,Math.PI*2);ctx.stroke()}}
 if(e.hp<e.maxHp||e.boss){const width=e.boss?100:e.r*2;ctx.fillStyle='#352c32';ctx.fillRect(-width/2,-e.r-14,width,4);ctx.fillStyle=e.boss?'#ff96bd':'#b6d982';ctx.fillRect(-width/2,-e.r-14,width*Math.max(0,e.hp/e.maxHp),4)}if(e.boss){ctx.font='bold 10px sans-serif';ctx.textAlign='center';ctx.fillStyle='#ffc9db';ctx.fillText(e.hp<e.maxHp*.5?'HOLLOW KING · ENRAGED':'HOLLOW KING',0,-e.r-22)}ctx.restore()}
function terrainRand(x,y,k=0){const n=Math.sin(x*127.1+y*311.7+k*74.7)*43758.5453;return n-Math.floor(n)}
function drawGround(px,py){const size=96;for(let tx=Math.floor((px-W/2)/size)-1;tx<=Math.ceil((px+W/2)/size);tx++)for(let ty=Math.floor((py-H/2)/size)-1;ty<=Math.ceil((py+H/2)/size);ty++){const x=tx*size,y=ty*size,n=terrainRand(tx,ty);ctx.fillStyle=['#122019','#14231a','#17271c','#15231b'][Math.floor(n*4)];ctx.fillRect(x,y,size,size);ctx.strokeStyle='#233429';ctx.lineWidth=1;ctx.strokeRect(x+2,y+2,size-4,size-4);
 for(let i=0;i<3;i++){const sx=x+terrainRand(tx,ty,i+2)*size,sy=y+terrainRand(tx,ty,i+8)*size;ctx.fillStyle='#304431';ctx.globalAlpha=.4;ctx.beginPath();ctx.ellipse(sx,sy,7+i*3,3+i,terrainRand(tx,ty,i+12)*3,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}
 if(n>.77){ctx.strokeStyle='#40513a';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x+22,y+18);ctx.lineTo(x+45,y+40);ctx.lineTo(x+39,y+57);ctx.lineTo(x+67,y+72);ctx.stroke()}
 if(n<.13){ctx.fillStyle='#253d27';ctx.beginPath();ctx.ellipse(x+49,y+46,25,15,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#577248';for(let i=0;i<4;i++){ctx.beginPath();ctx.moveTo(x+34+i*8,y+48);ctx.lineTo(x+31+i*8,y+37-i%2*6);ctx.stroke()}}
 if(n>.94){ctx.fillStyle='#0a140e66';ctx.beginPath();ctx.ellipse(x+43,y+48,22,8,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#3b4c3c';ctx.beginPath();ctx.moveTo(x+24,y+43);ctx.lineTo(x+31,y+29);ctx.lineTo(x+49,y+26);ctx.lineTo(x+61,y+41);ctx.lineTo(x+51,y+48);ctx.closePath();ctx.fill();ctx.strokeStyle='#65755b';ctx.beginPath();ctx.moveTo(x+31,y+29);ctx.lineTo(x+49,y+26);ctx.lineTo(x+57,y+36);ctx.stroke()}
 if(n>.52&&n<.56){ctx.strokeStyle='#64a88b';ctx.globalAlpha=.5;ctx.lineWidth=2;ctx.beginPath();ctx.arc(x+48,y+48,18,0,Math.PI*2);ctx.moveTo(x+48,y+34);ctx.lineTo(x+48,y+62);ctx.moveTo(x+37,y+43);ctx.lineTo(x+59,y+53);ctx.stroke();ctx.globalAlpha=1}
 } }
function draw(){ctx.fillStyle='#09140f';ctx.fillRect(0,0,W,H);const px=run?run.x:0,py=run?run.y:0;ctx.save();ctx.translate(W/2-px,H/2-py);drawGround(px,py);
 for(const z of zones){ctx.globalAlpha=Math.min(.5,z.t*.3);ctx.fillStyle=z.color;ctx.beginPath();ctx.arc(z.x,z.y,z.r,0,Math.PI*2);ctx.fill();if(z.kind==='mine'){ctx.globalAlpha=1;ctx.strokeStyle=z.color;ctx.stroke();ctx.fillStyle='#fff';ctx.fillRect(z.x-2,z.y-2,4,4)}}ctx.globalAlpha=1;
 for(const g of gems){ctx.fillStyle='#c6fc70';ctx.save();ctx.translate(g.x,g.y);ctx.rotate(Math.PI/4);ctx.fillRect(-3,-3,6,6);ctx.restore()}
 for(const h of hazards){ctx.strokeStyle='#ff8c8c';ctx.fillStyle=h.wait>0?'#ff77772a':'#ff8d7988';ctx.lineWidth=2;ctx.beginPath();ctx.arc(h.x,h.y,h.r,0,Math.PI*2);ctx.fill();ctx.stroke();if(h.wait>0){ctx.beginPath();ctx.arc(h.x,h.y,h.r*Math.max(.1,1-h.wait),0,Math.PI*2);ctx.stroke()}}
 for(const e of enemies)drawEnemy(e);
 for(const b of hostileShots){ctx.fillStyle='#ffb181';ctx.strokeStyle='#ff6868';ctx.lineWidth=2;ctx.beginPath();ctx.arc(b.x,b.y,b.r,0,Math.PI*2);ctx.fill();ctx.stroke()}
 for(const b of shots){ctx.fillStyle=b.color;ctx.save();ctx.translate(b.x,b.y);if(b.axe){ctx.rotate(run.total*12);ctx.fillRect(-b.r,-4,b.r*2,8);ctx.fillRect(-4,-b.r,8,b.r*2)}else{ctx.rotate(Math.atan2(b.vy,b.vx));ctx.fillRect(-7,-b.r,14,b.r*2)}ctx.restore()}
 if(run){ctx.save();ctx.translate(run.x,run.y);ctx.globalAlpha=run.inv>0?.65+Math.sin(run.total*25)*.25:1;ctx.strokeStyle=run.char.color;ctx.lineWidth=1.5;ctx.beginPath();ctx.ellipse(0,12,16,6,0,0,Math.PI*2);ctx.stroke();const avatar=getAvatar(run.char);const moving=touch?Math.hypot(touch.dx,touch.dy)>.1:Object.values(keys).some(Boolean);const bob=moving?Math.sin(run.total*16)*1.8:0;if(avatar?.complete&&avatar.naturalWidth>0){ctx.save();if(run.dx<0)ctx.scale(-1,1);ctx.drawImage(avatar,-26,-31+bob,52,52);ctx.restore()}else{ctx.fillStyle=run.char.color;ctx.beginPath();ctx.arc(0,0,13,0,Math.PI*2);ctx.fill()}ctx.restore()}
 for(const e of effects){ctx.globalAlpha=Math.min(1,e.t*4);ctx.strokeStyle=e.color;ctx.fillStyle=e.color;ctx.lineWidth=3;if(e.kind==='text'){ctx.font='bold 11px sans-serif';ctx.textAlign='center';ctx.fillText(e.text,e.x,e.y-(.55-e.t)*24)}else if(e.kind==='line'){ctx.beginPath();ctx.moveTo(e.x,e.y);ctx.lineTo((e.x+e.x2)/2+10,(e.y+e.y2)/2-10);ctx.lineTo(e.x2,e.y2);ctx.stroke()}else if(e.kind==='slash'){ctx.lineWidth=10;ctx.beginPath();ctx.arc(e.x,e.y,e.r,e.a-2,e.a+2);ctx.stroke()}else{ctx.beginPath();ctx.arc(e.x,e.y,e.r*(e.kind==='ring'?1-e.t*.7:1),0,Math.PI*2);e.kind==='orb'?ctx.fill():ctx.stroke()}}ctx.globalAlpha=1;ctx.restore();if(ctx.createRadialGradient){const haze=ctx.createRadialGradient(W/2,H/2,Math.min(W,H)*.18,W/2,H/2,Math.max(W,H)*.7);haze.addColorStop(0,'#07120b00');haze.addColorStop(1,'#030a0788');ctx.fillStyle=haze;ctx.fillRect(0,0,W,H)}}
function frame(t){let dt=Math.min(.033,(t-last)/1000||.016);last=t;update(dt);draw();requestAnimationFrame(frame)}
addEventListener('keydown',e=>{const k=e.key.length===1?e.key.toLowerCase():e.key;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(k))e.preventDefault();keys[k]=true;if(k===' ')dash();if(k==='e')activateAbilities();if(k==='p'||k==='Escape')pause()});addEventListener('keyup',e=>{keys[e.key.length===1?e.key.toLowerCase():e.key]=false});addEventListener('blur',()=>{resetInput();if(state==='playing')pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='playing')pause()});$('#pause').onclick=pause;$('#dash').onclick=dash;
canvas.addEventListener('pointerdown',e=>{if(state!=='playing'||touch)return;canvas.setPointerCapture(e.pointerId);touch={id:e.pointerId,x:e.clientX,y:e.clientY,dx:0,dy:0};const stick=$('#stick');stick.style.display='block';stick.style.left=(e.clientX-55)+'px';stick.style.top=(e.clientY-55)+'px';stick.firstElementChild.style.transform='translate(0,0)'});canvas.addEventListener('pointermove',e=>{if(!touch||touch.id!==e.pointerId)return;let dx=e.clientX-touch.x,dy=e.clientY-touch.y,d=Math.hypot(dx,dy),scale=Math.min(1,42/(d||1));touch.dx=dx*scale/42;touch.dy=dy*scale/42;$('#stick i').style.transform=`translate(${dx*scale}px,${dy*scale}px)`});function endTouch(e){if(touch?.id===e.pointerId){touch=null;$('#stick').style.display='none'}}canvas.addEventListener('pointerup',endTouch);canvas.addEventListener('pointercancel',endTouch);canvas.addEventListener('lostpointercapture',endTouch);
$('#skill').onclick=activateAbilities;$('#cheat-button').onclick=()=>utility('cheats');$('#achievement-button').onclick=()=>utility('achievements');checkAchievements();title();requestAnimationFrame(frame);

